-- GENERATED by `wfj generate` from data/gossip/gossip-e6.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["e600d32c88bbea26"] = { "L'anziano Bloodhoof si trova al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧, a Mulgore.", "." },
  ["e60a96bc671f7dbb"] = { "Puoi aiutarmi a scendere?", "." },
  ["e60e9b9999bb49b0"] = { "Ci sono molti locali dove bere qualcosa a ⟦Stormwind=Roccavento⟧, ma solo uno ti permette di passare la notte. Va' al Gilded Rose nel ⟦Trade District=Quartiere del Commercio⟧. Ho sentito che il prezzo di una stanza è ragionevole e le lenzuola sono pulite.", "." },
  ["e61bfef12c52f424"] = { "Hamhock nei guai! Hamhock serve aiuto!", "." },
  ["e61c65437310ea10"] = { "Bale può insegnarti le vie della sopravvivenza. Cercalo sull'⟦Hunter Rise=Altura dei Cacciatori⟧.", "." },
  ["e62aea1f1939dc0b"] = { "Cerca Sayoc e Hanashi nella ⟦Valley of Honor=Valle dell'Onore⟧, dentro Arms of Legend. Bada a come parli con loro, o Sayoc potrebbe decidere di dare un pezzo di te in pasto a ⟦Grinning Dog=Cane Ringhiante⟧.", "." },
  ["e62b57f491acd04a"] = { "Ah sì, davvero? Allora, cos'hai per il nuovo pezzo grosso dei Gordok, Fengus?", "." },
  ["e63e7d0eaa10547d"] = { "Le tue abilità vanno oltre le mie, <straniero/straniera>. Parla con Hgarth al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧. Ti darà più conoscenze di quante possa dartene io.", "." },
  ["e64bcd8dcb4d2e31"] = { "Non c'è scampo!", "." },
  ["e652c64cdd7d1197"] = { "È ora di salvare l'intera razza gnomesca. Speriamo bene!", "." },
  ["e655c168221cec01"] = { "Non posso aiutarti: il tuo lavoro supera il mio. Parla con Arthur Moore, laggiù vicino alle bare. Potrà addestrarti ulteriormente.", "." },
  ["e655f89a3e32b3db"] = { "Se dimostri di essere <un/una> <vero/vera> <alleato/alleata>, potrei prendere in considerazione l'idea di addestrarti...", "." },
  ["e65a12c1620c41dd"] = { "Non lo sappiamo.\n\nI ⟦Dark Iron=Ferroscuro⟧ sopravvissuti raggiunsero la montagna e cominciarono a ricostruire la loro città.\n\nDalle ceneri di Thaurissan sorsero allora i ⟦Blackrock Spire=Bastioni di Roccianera⟧ e la nuova nazione ⟦Dark Iron=Ferroscuro⟧. Altre fortificazioni furono erette nella ⟦Searing Gorge=Gorgia Rovente⟧, nella zona nota come Caldera Magmatica.\n\nCominciarono a circolare storie di un antico male che controllava il regno dei ⟦Dark Iron=Ferroscuro⟧.", "." },
  ["e65ee30121a94f77"] = { "Non conosco questo Eye of the Tiger di cui alcuni parlano, ma posso mostrarti come usare gli artigli della tigre.", "." },
  ["e660bd8352ababe0"] = { "Sono qui! Sono qui! Aiutatemi!", "." },
  ["e668361fd41c67f2"] = { "Fornisco alla Fortezza varie reliquie necessarie per gli incantesimi, oltre ad altri reagenti alchemici.", "." },
  ["e670c8391602c750"] = { "Non sono in grado di elaborare il tuo riferimento cronologico rispetto alla registrazione di questi dati, chiedo scusa.\n\nIl trogg conserva in parte la composizione dei vari composti del nucleo di pietra di Azeroth, ma la perdita di capacità cognitive rende questa variante inaccettabile per i Creatori.\n\nIl trogg si riproduce come una biomassa standard. Per impostazione predefinita consuma pietra e qualsiasi altra cosa riesca a procurarsi, compresi altri trogg. Il cannibalismo è considerato inaccettabile dai Creatori.", "." },
  ["e674cd8657d241c3"] = { "È molto triste pensare a ciò che è capitato a quelle povere anime non morte. Troverai l'arcimago Shymm immerso nei suoi pensieri vicino alle Pools of Vision, sotto l'⟦Spirit Rise=Altura degli Spiriti⟧.", "." },
  ["e679710863d25484"] = { "Sia lodata la Luce, sei qui! Sfodera la spada, ho dei centauri alle calcagna!", "." },
  ["e67d746078ee03f0"] = { "Perdonami, padre! Ti prego...", "." },
  ["e67ed60b58fc8743"] = { "Forza, ragazzi! È ora di alzarsi", "." },
  ["e6817059d132428b"] = { "Cerchi Plucky? Be', non dire in giro che te l'ho detto io, ma... forse se chiedi a Kronkrider, su nella torre, te lo dirà...", "." },
  ["e6879ce35f7c0a91"] = { "Quasi fatto...", "." },
  ["e689e4b59a89dfd5"] = { "Vai avanti senza di me! Raggiungerò il ⟦Tarren Mill=Mulino di Tarren⟧ per conto mio.", "." },
  ["e68b0921fa02efc6"] = { "Assaggia il mio potere!", "." },
  ["e691be0f2a2c9024"] = { "Co... dove mi trovo? Che... debolezza..", "." },
  ["e6986385632d05f0"] = { "Ho perso i miei ⟦Zandalar Haruspex's Bracers=Bracciali dell'Aruspice degli Zandalari⟧ e me ne serve un altro paio.", "." },
  ["e6a38ef9ddca142d"] = { "Parla con me per una birra gratis al Pig and Whistle!", "." },
  ["e6a78832ee90bba6"] = { "Troverai l'anziano Totem Truce al ⟦Lariss Pavilion=Padiglione di Lariss⟧, a Feralas.", "." },
  ["e6a824dc15398cf3"] = { "Cerchi Shenthul della Shadowswift Brotherhood, eh? Nel Varcolargo, di fronte a Droffers and Son Salvage, cerca un tunnel che scende nella Cleft of Shadow.", "." },
  ["e6ae75f1160c3112"] = { "Ho perso il mio ⟦Cloak of the Gathering Storm=Mantello della Tempesta Crescente⟧. Puoi sostituirmelo?", "." },
  ["e6b27eef0245d289"] = { "Vorrei comprare da te.", "." },
  ["e6bee56fc3fb12f6"] = { "Senza offesa per chiunque sia questo Nijel, ma questo accampamento non è il posto più comodo dove abbia mai passato la notte, se capisci cosa intendo, {name}.", "." },
  ["e6c18cdda63ea1f7"] = { "Aspetta... tu non sei mio marito. Ma deve averti mandato lui. E tu... sembri... <squisito/squisita>!", "." },
  ["e6c6e6120ea5cbeb"] = { "Penserai che, solo perché viviamo su un'isola galleggiante, non ci sia bisogno di minatori come me. Eppure, dopo tante migliaia di anni, riusciamo ancora a scavare un sacco di cose interessanti. \r\n\nÈ quasi come se ci fosse una forza invisibile che ogni tanto crea di continuo nuovi giacimenti di minerali. Ma la magia è fatta così, no?\r\n\nComunque, se ti serve addestramento come minatore, sono io la persona shen'dorei che fa per te.", "." },
  ["e6c78102f03c8cca"] = { "Ho perso il ⟦Brazier of Beckoning=Braciere del Richiamo⟧!", "." },
  ["e6c8e6949e03cb21"] = { "Svegli, cani! Abbiamo un'operazione da mandare avanti qui!", "." },
  ["e6ce3dca2c4bd8b5"] = { "Ce n'è uno del Flagello, proprio laggiù!", "." },
  ["e6d21164913e7b5a"] = { "Sai dove porta tutto questo, vero, {name}? Non c'è modo che sopravviva... guardala. La cosa migliore per lei ora è aiutarci a trovare una cura per la pestilenza. L'acqua che ha bevuto potrebbe contenere un indizio che ci aiuti a capire come. Morirà comunque: tanto vale che, prima di morire, faccia qualcosa di nobile per il nostro popolo. Non sei d'accordo?", "." },
  ["e6dd3cfba6f4776e"] = { "Sì, ragazzi! Le cose stanno per mettersi parecchio male.", "." },
  ["e6dd83b53800a98d"] = { "No, no, ti prego, continua... è solo che l'aria quassù è così, ehm, fumosa.", "." },
  ["e6dda9992ae372f5"] = { "Chi è furbo punta sugli gnomi per la prossima corsa! Piazza le tue scommesse finché sei in tempo!", "." },
  ["e6ded8265e9ea0c6"] = { "Considerati <fortunato/fortunata>, mortale. Almeno il tuo cadavere è ancora piuttosto presentabile.", "." },
  ["e6e88f72a1295e46"] = { "<Signore/Signora>, sì, <signore/signora>! Il soldato semplice Porter a rapporto, a tua disposizione per raccogliere il cuoio medio che ti serve. La Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧ si avvicina e dobbiamo essere preparati il più possibile.\n\nCome vedi, abbiamo raccolto esattamente $2063w pezzi di cuoio medio, e mi hanno incaricato di raccoglierne in totale $2064w.", "." },
  ["e6edd690d53d5db7"] = { "Il ⟦Shrine of Remulos=Santuario di Remulos⟧ è un luogo sacro per noi del ⟦Cenarion Circle=Circolo Cenariano⟧, qui a ⟦Moonglade=Radaluna⟧... quindi comportati come si addice a un visitatore.\n\nA un visitatore che non vuole la mia scimitarra piantata in corpo, s'intende.", "." },
  ["e6ee43474a5e17b8"] = { "I vivi sono qui!", "." },
  ["e6f0de1096d508af"] = { "Dimmi cosa ti serve, e fai in fretta.", "." },
  ["e6f2cafa845e96f1"] = { "Che ne dici di consegnare un messaggio per me?", "." },
  ["e6f3c3c0221d9abd"] = { "%s continua a crescere!", "." },
  ["e6fa2264ae516599"] = { "Jin'rokh, ho bisogno di aiuto per recuperare un pezzo della mia Freethinker's Armor.", "." },
  ["e6fba50dc2e75c01"] = { "Fiamma Furente", "." },
  ["e6fcb3af281ebc1a"] = { "Il libro narra di draghi che si uniscono contro un altro drago, più potente, di nome Alamorte. Da quel che riesci a capire, lo stormo cromatico era stato quasi scatenato sul mondo. Gli Aspetti erano pronti.", "." },
  ["e6feed5aaecff586"] = { "Cos'è l'armatura della Redenzione?", "." },
})
